USE campusconnect;
CREATE OR REPLACE VIEW v_club_membership_counts AS SELECT c.club_id,c.club_name,c.category,c.status,COUNT(cm.membership_id) AS total_members,SUM(cm.membership_status='ACTIVE') AS active_members FROM clubs c LEFT JOIN club_memberships cm USING(club_id) GROUP BY c.club_id;
CREATE OR REPLACE VIEW v_club_officers AS SELECT c.club_id,c.club_name,s.student_id,s.name,s.email,cm.membership_role FROM club_memberships cm JOIN clubs c USING(club_id) JOIN students s USING(student_id) WHERE cm.membership_role<>'MEMBER' AND cm.membership_status='ACTIVE';
CREATE OR REPLACE VIEW v_event_overview AS SELECT e.event_id,e.club_id,e.venue_id,e.event_name,e.description,e.event_date,TIME_FORMAT(e.start_time,'%H:%i:%s') AS start_time,TIME_FORMAT(e.end_time,'%H:%i:%s') AS end_time,e.capacity,e.registration_deadline,e.event_status,e.created_at,c.club_name,v.venue_name,v.building,v.room_number,COUNT(DISTINCT CASE WHEN r.registration_status='REGISTERED' THEN r.registration_id END) AS registered_count,COUNT(DISTINCT CASE WHEN r.registration_status='WAITLISTED' THEN r.registration_id END) AS waitlisted_count FROM events e JOIN clubs c USING(club_id) JOIN venues v USING(venue_id) LEFT JOIN event_registrations r USING(event_id) GROUP BY e.event_id;
CREATE OR REPLACE VIEW v_upcoming_events AS SELECT * FROM v_event_overview WHERE event_status IN ('UPCOMING','ONGOING') ORDER BY event_date,start_time;
CREATE OR REPLACE VIEW v_event_popularity AS SELECT e.event_id,e.event_name,c.club_name,COUNT(r.registration_id) AS registrations FROM events e JOIN clubs c USING(club_id) LEFT JOIN event_registrations r ON r.event_id=e.event_id AND r.registration_status<>'CANCELLED' GROUP BY e.event_id;
CREATE OR REPLACE VIEW v_event_attendance AS SELECT e.event_id,e.event_name,COUNT(CASE WHEN r.attendance_status='PRESENT' THEN 1 END) AS present_count,COUNT(CASE WHEN r.registration_status='REGISTERED' THEN 1 END) AS registered_count,ROUND(100*COUNT(CASE WHEN r.attendance_status='PRESENT' THEN 1 END)/NULLIF(COUNT(CASE WHEN r.registration_status='REGISTERED' THEN 1 END),0),2) AS attendance_percentage FROM events e LEFT JOIN event_registrations r USING(event_id) GROUP BY e.event_id;
CREATE OR REPLACE VIEW v_event_feedback_summary AS SELECT e.event_id,e.event_name,COUNT(f.feedback_id) AS feedback_count,ROUND(AVG(f.rating),2) AS average_rating FROM events e LEFT JOIN event_feedback f USING(event_id) GROUP BY e.event_id;
CREATE OR REPLACE VIEW v_club_activity_report AS SELECT c.club_id,c.club_name,COUNT(DISTINCT cm.membership_id) AS memberships,COUNT(DISTINCT e.event_id) AS events_organised FROM clubs c LEFT JOIN club_memberships cm USING(club_id) LEFT JOIN events e USING(club_id) GROUP BY c.club_id;
CREATE OR REPLACE VIEW v_student_activity AS SELECT s.student_id,s.name,s.department,COUNT(DISTINCT cm.club_id) AS clubs_joined,COUNT(DISTINCT r.event_id) AS events_registered,COUNT(DISTINCT CASE WHEN r.attendance_status='PRESENT' THEN r.event_id END) AS events_attended FROM students s LEFT JOIN club_memberships cm ON cm.student_id=s.student_id AND cm.membership_status='ACTIVE' LEFT JOIN event_registrations r ON r.student_id=s.student_id AND r.registration_status='REGISTERED' GROUP BY s.student_id;
CREATE OR REPLACE VIEW v_event_roster AS SELECT r.registration_id,r.event_id,r.student_id,s.name,s.email,r.registration_status,r.attendance_status,r.registered_at FROM event_registrations r JOIN students s USING(student_id);
